import math

def build_agent(sandbox):
    # The sled is already present in the environment, so no additional setup is needed
    return None

def agent_action(sandbox, agent_body, step_count):
    # Retrieve current position and velocity
    x, y = sandbox.get_sled_position()
    vx, vy = sandbox.get_sled_velocity()

    # Determine the next target based on checkpoint status
    if not sandbox.get_checkpoint_a_reached() and not sandbox.get_checkpoint_b_reached():
        target_x, target_y = 18.25, 4.15  # Center of Alpha checkpoint
    elif sandbox.get_checkpoint_a_reached() and not sandbox.get_checkpoint_b_reached():
        target_x, target_y = 23.75, 2.85  # Center of Beta checkpoint
    else:
        target_x, target_y = 30, 2.5  # Final target zone

    # Calculate direction vector to target
    dx = target_x - x
    dy = target_y - y
    distance = math.hypot(dx, dy)

    # Normalize direction vector if not at target
    if distance < 0.1:
        dx_normalized = 0
        dy_normalized = 0
    else:
        dx_normalized = dx / distance
        dy_normalized = dy / distance

    # Calculate current speed
    current_speed = math.hypot(vx, vy)
    desired_speed = 5.0  # Base desired speed

    # Adjust desired speed based on distance to target
    if distance > 15:
        desired_speed = 5.0
    elif distance > 10:
        desired_speed = 4.5
    elif distance > 5:
        desired_speed = 4.0
    elif distance > 2:
        desired_speed = 3.5
    else:
        desired_speed = 3.0

    # Adjust thrust magnitude based on distance and speed
    if distance > 15:
        thrust_magnitude = 1200
    elif distance > 10:
        thrust_magnitude = 1400
    elif distance > 5:
        thrust_magnitude = 1600
    elif distance > 2:
        thrust_magnitude = 1800
    else:
        thrust_magnitude = 2000

    # Adjust thrust based on current speed
    if current_speed < desired_speed:
        thrust_magnitude += max(0, (desired_speed - current_speed) * 100)
    elif current_speed > desired_speed:
        thrust_magnitude -= max(0, (current_speed - desired_speed) * 100)

    # Apply vertical correction for y-position
    y_error = target_y - y
    if abs(y_error) > 0.5:
        # Apply stronger correction for y, adjusted to ensure proper descent
        y_correction = y_error * 1.0  # Increased correction factor for better control
        f2 = thrust_magnitude * dy_normalized + y_correction
        f1 = thrust_magnitude * dx_normalized
    else:
        f1 = thrust_magnitude * dx_normalized
        f2 = thrust_magnitude * dy_normalized

    # Ensure minimum speed to avoid stalling
    if current_speed < 1.0:
        # Add additional thrust to maintain speed
        f1 += 1000 * dx_normalized
        f2 += 1000 * dy_normalized

    # Apply thrust with dynamic adjustment
    sandbox.apply_thrust(f1, f2)
